Method: fr.baretto.ollamassist.chat.askfromcode.EditorListener#handleEditorRelease
Signature: private static void handleEditorRelease(Editor editor)
Body: {
    synchronized (LISTENER_MAP) {
        OllamAssistSelectionListener listener = LISTENER_MAP.remove(editor);
        if (listener != null) {
            editor.getSelectionModel().removeSelectionListener(listener);
        }
    }
}
Method: fr.baretto.ollamassist.chat.askfromcode.EditorListener#attachListeners
Signature: public static void attachListeners()
Body: {
    EditorFactory editorFactory = EditorFactory.getInstance();
    editorFactory.addEditorFactoryListener(new EditorFactoryListener() {

        @Override
        public void editorCreated(@NotNull EditorFactoryEvent event) {
            handleEditorCreation(event.getEditor());
        }

        @Override
        public void editorReleased(@NotNull EditorFactoryEvent event) {
            handleEditorRelease(event.getEditor());
        }
    }, PLUGIN_DISPOSABLE);
    initializeExistingEditors();
}
